window.ScripturaLexicons.BDAG_PART_0026 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ampelourgos-bdag\" data-source=\"BDAG\" data-search=\"ἀμπελουργός ampelourgos viticultor vinhateiro jardineiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμπελουργός</td><td>Substantivo masculino</td><td>viticultor; jardineiro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ampelon-bdag\" data-source=\"BDAG\" data-search=\"ἀμπελών ampelon vinhedo vinha pomar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμπελών</td><td>Substantivo masculino</td><td>vinhedo; vinha</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ampliatos-bdag\" data-source=\"BDAG\" data-search=\"Ἀμπλιᾶτος Ampliatos Amplíato nome próprio Romanos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμπλιᾶτος</td><td>Nome próprio masculino</td><td>Amplíato</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amynomai-bdag\" data-source=\"BDAG\" data-search=\"ἀμύνομαι amynomai ajudar socorrer defender retaliar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμύνομαι</td><td>Verbo</td><td>ajudar; socorrer; defender</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphiazo-bdag\" data-source=\"BDAG\" data-search=\"ἀμφιάζω amphiazo vestir revestir variante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιάζω</td><td>Verbo</td><td>vestir; revestir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphiballo-bdag\" data-source=\"BDAG\" data-search=\"ἀμφιβάλλω amphiballo lançar rede tarrafa lançar ao redor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιβάλλω</td><td>Verbo</td><td>lançar a rede; lançar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphiblestron-bdag\" data-source=\"BDAG\" data-search=\"ἀμφίβληστρον amphib lestron tarrafa rede circular de lançamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφίβληστρον</td><td>Substantivo neutro</td><td>tarrafa; rede circular de lançamento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphibolia-bdag\" data-source=\"BDAG\" data-search=\"ἀμφιβολία amphibolia disputa contenda discussão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιβολία</td><td>Substantivo feminino</td><td>disputa; contenda</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphiezo-bdag\" data-source=\"BDAG\" data-search=\"ἀμφιέζω amphiezo vestir revestir variante helenística BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιέζω</td><td>Verbo</td><td>vestir; revestir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphiennymi-bdag\" data-source=\"BDAG\" data-search=\"ἀμφιέννυμι amphiennymi vestir revestir trajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφιέννυμι</td><td>Verbo</td><td>vestir; trajar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphipolis-bdag\" data-source=\"BDAG\" data-search=\"Ἀμφίπολις Amphipolis Anfípolis Macedônia Via Egnatia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμφίπολις</td><td>Nome próprio feminino</td><td>Anfípolis</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphodon-bdag\" data-source=\"BDAG\" data-search=\"ἄμφοδον amphodon bairro rua quarteirão cidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄμφοδον</td><td>Substantivo neutro</td><td>bairro; rua</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amphoteroi-bdag\" data-source=\"BDAG\" data-search=\"ἀμφότεροι amphoteroi ambos os dois todos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμφότεροι</td><td>Adjetivo / pronome</td><td>ambos; os dois; todos</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amometos-bdag\" data-source=\"BDAG\" data-search=\"ἀμώμητος amometos irrepreensível irrepreensivel sem mácula sem macula BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμώμητος</td><td>Adjetivo</td><td>irrepreensível; sem mácula</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amomon-bdag\" data-source=\"BDAG\" data-search=\"ἄμωμον amomon amomo planta aromática indiana especiaria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄμωμον</td><td>Substantivo neutro</td><td>amomo; planta aromática indiana</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amomos-bdag\" data-source=\"BDAG\" data-search=\"ἄμωμος amomos sem defeito sem mácula irrepreensível inocente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄμωμος</td><td>Adjetivo</td><td>sem defeito; irrepreensível</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amomos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀμώμως amomos irrepreensivelmente sem culpa sem censura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀμώμως</td><td>Advérbio</td><td>irrepreensivelmente; sem culpa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amon-bdag\" data-source=\"BDAG\" data-search=\"Ἀμών Amon Amom nome próprio genealogia Manassés Josias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμών</td><td>Nome próprio masculino</td><td>Amom</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-amos-bdag\" data-source=\"BDAG\" data-search=\"Ἀμώς Amos Amós nome próprio genealogia Matatias Naum Manassés Josias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἀμώς</td><td>Nome próprio masculino</td><td>Amós</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-an-bdag\" data-source=\"BDAG\" data-search=\"ἄν an partícula particula contingência contingencia condição condicao eventualidade possibilidade potencialidade condicionalidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄν</td><td>Partícula</td><td>partícula de contingência / condicionalidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-ampelourgos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμπελουργός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ampelourgós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Aristófanes, Hipócrates e outros; Luciano, <em>Philops.</em> 11; inscrições, papiros, LXX; Fílon, <em>Plant.</em> 1.) <strong>Viticultor, jardineiro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.7</a>. — DELG s.v. <span class=\"greek\">ἄμπελος</span>. M-M.</p>\n</section></article><article id=\"entry-ampelon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμπελών</h1><div class=\"entry-meta\"><span class=\"greek\">ῶνος, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ampelṓn⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Teofrasto, <em>HP</em> 9, 10, 3; PEleph 14, 2; PHib 151; PPetr II, 140 [séc. III a.C.] e posteriormente; também LXX; TestLevi 2:12; ParJer 3:14; GrBar 1:2; Fílon; Jos., <em>Ant.</em> 8, 359.) <strong>Vinhedo, vinha.</strong></p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φυτεύειν ἀμπελῶνα\" data-meanings=\"plantar um vinhedo\">φυτεύειν ἀ.</span>, <strong>plantar um vinhedo</strong> — Gn 9.20 e outros; Fílon, <em>Virt.</em> 28; <em>Exs.</em> 128; PCairZen 300, 1 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.7</a> (compare Dt 20.6); Hs 5, 2, 2; 5, 6, 2. <span class=\"greek\">ἀ. καλοί</span>, <strong>vinhedos bem cultivados</strong>, Hm 10, 1, 5. <span class=\"greek\">χαρακοῦν ἀ.</span>, <strong>cercar um vinhedo</strong>, Hs 5, 2, 3; compare 5, 4, 1ss. <span class=\"greek\">σκάπτειν ἀ.</span>, <strong>cavar um vinhedo</strong> — Diodoro Sículo 4, 31, 7 —, Hs 5, 2, 4.</p>\n<p class=\"entry-text\">Nas parábolas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.1ss.</a>; 21.28ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.1ss.</a> — W. Kümmel, M. Goguel <em>Festschr.</em>, 1950, 120–131; M. Hengel, <em>ZNW</em> 59, 1968, 1–39 —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20.9ss.</a> — B. van Iersel, “D. Sohn” em <em>den synopt. Jesusworten</em>, 1964², 124–145; J. Derrett, <em>Law in the NT</em>, 1970, 286–312. Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.6</a>, onde pode significar <strong>pomar</strong>. Símbolo do povo cristão, Hs 5, 5, 3. — DELG s.v. <span class=\"greek\">ἄμπελος</span>. M-M.</p>\n</section></article><article id=\"entry-ampliatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμπλιᾶτος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Ampliâtos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Também <span class=\"greek\">-ίατος</span>; forma paralela <span class=\"greek\">Ἀμπλιάς</span>, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.8</a> como v.l., mais corretamente acentuada <span class=\"greek\">Ἀμπλιᾶς</span>; veja W-S. §6, 7g; B-D-F §125, 1 e 2.) <strong>Amplíato</strong>, nome comum de escravo: CIL II, 3771 [Espanha]; VI, 14918; 15509 [Roma]; IV, 1182; 1183 [Pompeia]; IG III, 1161, 8; 1892 [Atenas]; CIL III, 436 [Éfeso]. Destinatário de uma saudação, designado <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαπητὸς ἐν κυρίῳ\" data-meanings=\"amado no Senhor\">ἀγαπητὸς ἐν κυρίῳ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.8</a> — veja Lghtf., <em>Phil.</em> 1891, 172; Rouffiac 90; Ltzm., <em>Hdb.</em> ad loc. — M-M. s.v. <span class=\"greek\">Ἀμπλίας</span>.</p>\n</section></article><article id=\"entry-amynomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμύνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦amúnomai⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro, 3ª pessoa do singular <span class=\"greek\">ἀμυνεῖται</span>, Taciano 17:4; primeiro aoristo <span class=\"greek\">ἠμυνάμην</span> (Homero e outros; LXX; JosAs; ApcrEzk [Epifânio 70, 8]; porém, aqui tão raro quanto em inscrições — por exemplo SIG 780, 35; IAndrosIsis, Kyme 37 p. 124 P. — e papiros — por exemplo APF 3, 1906, p. 418, 71 —; Jos., <em>Bell.</em> 1, 319; 5, 129; <em>Ant.</em> 9, 9 e outros; Taciano 17, 2; 4).</p>\n<p class=\"entry-text\"><strong>Ajudar vindo em socorro de alguém, ajudar, assistir, defender alguém</strong> — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.59.16\" target=\"_blank\" rel=\"noopener noreferrer\">Is 59.16</a>; JosAs 23:11 cód. A [p. 75, 9 Bat.] —, usado absolutamente com <span class=\"greek\">ἐκδίκησιν ποιεῖν</span> a respeito de Moisés, que matou um egípcio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.24</a> — para o ático <span class=\"greek\">ἀμύνω</span>, veja B-D-F §316, 1. O BDAG observa que esse sentido é <strong>talvez preferível</strong> a <strong>retaliar</strong> — como Epicteto 4, 13, 7; JosAs 24:7. — DELG s.v. <span class=\"greek\">ἀμύνω</span>. M-M.</p>\n</section></article><article id=\"entry-amphiazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφιάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦amphiázō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma helenística por <span class=\"greek\">ἀμφιέννυμι</span>; veja Schwyzer I 244. Ocorre em Plutarco, <em>C. Gracch.</em> 835 [2, 3 Z.] v.l.; Vett. Val. 64, 9; Alcífron 3, 6, 3; OGI 200, 24; Sb 6949, 24; PIand 62, 14; LXX; Jos., <em>Bell.</em> 7, 131; <em>Ant.</em> 10, 11; AcThom 7 [Aa II/2, 110, 13]; Mel., <em>P.</em> 47, 330, <span class=\"greek\">ὁ κύριος … τὸν πάσχοντα ἀμφιασάμενος</span>. Forma paralela de <span class=\"greek\">ἀμφιέζω</span>: <strong>vestir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.28</a> v.l. [N.25 no texto]. — DELG. M-M.</p>\n</section></article><article id=\"entry-amphiballo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφιβάλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦amphibállō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<span class=\"greek\">βάλλω</span>, “lançar”; em diversos sentidos desde Homero; papiros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HAB.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hc 1.17</a>; TestJob 29:3; Just., <em>D.</em> 51, 2; 123, 7; Ath. <em>R.</em> 48, 21, no sentido “duvidar, hesitar”.) <strong>Lançar</strong>, termo técnico para o lançamento da rede circular de pesca — <span class=\"greek\">δίκτυον</span>, Geopon. 20, 12; <span class=\"greek\">ἀμφίβληστρον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HAB.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hc 1.17</a>.</p>\n<p class=\"entry-text\">Uso absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἶδεν Σίμωνα καὶ Ἀνδρέαν ἀμφιβάλλοντας ἐν τῇ θαλάσσῃ\" data-meanings=\"viu Simão e André lançando a rede no mar\">εἶδεν Σίμωνα κ. Ἀνδρέαν ἀμφιβάλλοντας ἐν τῇ θαλάσσῃ</span>, <strong>viu Simão e André lançando sua(s) rede(s) no mar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.16</a>. Compare PFlor 119, 3 [254 d.C.], <span class=\"greek\">οἱ ἁλιεῖς … ἀμφιβάλλουσι</span>; contudo, as palavras indicadas pelos pontos <strong>não podem ser restauradas com certeza</strong>, de modo que permanece duvidoso se ali o verbo é usado absolutamente. Veja também <span class=\"greek\">ἀμφιβολεύω</span>, PSI 901, 13; 22 [46 d.C.], e semelhantemente <span class=\"greek\">ἀμφιβολεύς</span>, PCorn 46, 6, paralelo a Jr 19.8.</p>\n<p class=\"entry-text\">D. Dalman, <em>Arbeit</em> VI: <em>Zeltleben, Vieh- u. Milchwirtschaft, Jagd, Fischfang</em>, 1939; L. Bunsmann, <em>De piscatorum in Graec. atque Rom. litteris usu</em>, diss. Münster, 1910. — DELG s.v. <span class=\"greek\">βάλλω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-amphiblestron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφίβληστρον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amphíblēstron⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Hesíodo, Heródoto e outros; Artemidoro 2, 14 p. 107, 13; LXX; DELG s.v. <span class=\"greek\">βάλλω</span> p. 63e.) <strong>Rede circular usada na pesca, tarrafa</strong>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βάλλειν ἀμφίβληστρον\" data-meanings=\"lançar uma tarrafa; lançar uma rede circular\">βάλλειν ἀ.</span>, <strong>lançar uma tarrafa</strong> — Esopo, <em>Fab.</em> 11 P., H-H. = 27 H., <span class=\"greek\">βάλλειν τὸ ἀμφ.</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.16</a> v.l. Veja <span class=\"greek\">ἀμφιβάλλω</span>.</p>\n</section></article><article id=\"entry-amphibolia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφιβολία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amphibolía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Compare <span class=\"greek\">ἀμφιβάλλω</span>; Heródoto e outros em vários sentidos; Aristóteles; SIG 827 Tit. F col. V, 6; PLond 1716, 8 [séc. VI d.C.]; Jos., <em>Bell.</em> 3, 434; Ath. 11, 2; <em>R.</em> 60, 15.) <strong>Disputa, contenda</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφιβολίαν ἔχειν μετά τινος\" data-meanings=\"ter uma disputa com alguém\">ἀ. ἔχειν μετά τινος</span>, <strong>ter uma disputa com alguém</strong>, D 14:2. — B. 1244.</p>\n</section></article><article id=\"entry-amphiezo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφιέζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦amphiézō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma helenística paralela a <span class=\"greek\">ἀμφιάζω</span> — veja também <span class=\"greek\">ἀμφιέννυμι</span>. <em>An. Ox.</em> II 338: <span class=\"greek\">τὸ μὲν ἀμφιέζω ἐστὶ κοινῶς, τὸ δὲ ἀμφιάζω δωρικόν</span>, isto é, “<span class=\"greek\">ἀμφιέζω</span> é usado no vernáculo, e <span class=\"greek\">ἀμφιάζω</span> é dórico”. <strong>Vestir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.28</a>; os manuscritos variam entre <span class=\"greek\">ἀ.</span>, <span class=\"greek\">ἀμφιέζει</span> e <span class=\"greek\">ἀμφιέννυσιν</span>. Compare B-D-F §29, 2; 73; 101; W-S. §15; Mlt-H. 68; 228; Rdm. 44; 225.</p>\n</section></article><article id=\"entry-amphiennymi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφιέννυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦amphiénnumi⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἠμφιέσαντο</span>, 4Rs 17.9; perfeito passivo, 1ª pessoa do plural <span class=\"greek\">ἠμφιέσμεθα</span>, Just., <em>D.</em> 116, 1; particípio <span class=\"greek\">ἠμφιεσμένος</span>, POxy 850 [AcJ], 26s., restaurado. De <span class=\"greek\">ἕννυμι</span>, “vestir”; Eliano, <em>NA</em> 4, 46 p. 102, 17; Jos., <em>Ant.</em> 8, 186; Just., <em>D.</em> 116, 1 — em Zc 3.3, <span class=\"greek\">ἐνδέδυμένος</span> — <span class=\"greek\">ἠμφιέσμεθα</span>; compare W-S. §12, 6; B-D-F §69, 1; Mlt-H. 192. Também desde Homero; inscrições; PFouad 10, 8; BGU 388, 41.</p>\n<p class=\"entry-text\"><strong>Vestir, trajar</strong>, com acusativo daquilo que é vestido: <span class=\"greek\">τὸν χόρτον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.30</a>. Na passiva — compare Jos., <em>Bell.</em> 4, 473; <em>Ant.</em> 15, 403 —, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν μαλακοῖς ἱματίοις ἠμφιεσμένος\" data-meanings=\"vestido com roupas macias; trajado com vestes finas\">ἐν μαλακοῖς (ἱματίοις) ἠ.</span>, <strong>vestido com roupas macias</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.28</a> v.l. — sobre a construção, B-D-F §159, 1. De sementes, AcPlCor 2:26; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.37s.</a> Sobre Lc 12.28, veja <span class=\"greek\">ἀμφιάζω</span>. — DELG s.v. <span class=\"greek\">ἕννυμι</span>. M-M.</p>\n</section></article><article id=\"entry-amphipolis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμφίπολις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Amphípolis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Anfípolis</strong>, capital da Macedônia sudeste, assim chamada porque o rio Estrimão corre ao seu redor — Tucídides 4, 102, 4; Apiano, <em>Bell. Civ.</em> 4, 104 §437; 4, 107 §447 —, posto militar na Via Egnatia, a estrada principal de Roma para a Ásia. Paulo passou por <span class=\"greek\">Ἀμφίπολις</span> numa viagem de Filipos para Tessalônica, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.1</a>. — O. Hirschfeld em Pauly-W. I 1949ss.; PECS 51s. — bibliografia.</p>\n</section></article><article id=\"entry-amphodon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄμφοδον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ámphodon⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Aristófanes; Hipérides, Fgm. 137; inscrições — SIG 961 com nota; OGI 483, 80 — e papiros — UPZ 77 I, 6 [163 a.C.]; PLond II, 208, 7 p. 67; 225, 4 p. 8 e outros; veja Preisigke, <em>Fachwörter</em> — desde o séc. II a.C.; Jr 17.27; 30.33; JosAs 2:13.) Primariamente, <strong>“um bairro da cidade”</strong>, cercado e atravessado por ruas; depois, <strong>rua</strong>. Hesíquio explica <span class=\"greek\">ἄμφοδα· αἱ ῥῦμαι. ἀγυιαί. δίοδοι</span>.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔξω ἐπὶ τοῦ ἀμφόδου\" data-meanings=\"fora, na rua\">ἔξω ἐπὶ τοῦ ἀ.</span>, <strong>fora, na rua</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11.4</a> — exemplos de <span class=\"greek\">ἐπὶ τοῦ ἀ.</span> em papiros em Mayser 261, 1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τρέχειν εἰς τὸ ἄμφοδον\" data-meanings=\"correr para a rua\">τρέχειν εἰς τὸ ἀ.</span>, <strong>correr para a rua</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.28</a> D; compare AcPlTh, Aa I 243, 6. — M-M.</p>\n</section></article><article id=\"entry-amphoteroi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμφότεροι</h1><div class=\"entry-meta\"><span class=\"greek\">αι, α</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amphóteroi⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(DELG s.v. <span class=\"greek\">ἄμφω</span>; desde Homero.) <span class=\"sense-number\">1.</span> <strong>Ambos, os dois.</strong> Jos., <em>Ant.</em> 16, 125; Just.; Taciano 1, 2; Ath. <em>R.</em> 64, 30 e outros; Dg 9:6. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμφότεροι συντηροῦνται\" data-meanings=\"ambos são preservados\">ἀ. συντηροῦνται</span>, <strong>ambos — o vinho e os odres — são preservados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.38</a> v.l.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. εἰς βόθυνον (ἐμ-)πεσοῦνται</span>, <strong>ambos — o guia e aquele que ele guia — cairão no poço</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.39</a>. Compare Mt 13.30. <span class=\"greek\">ἦσαν δίκαιοι ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.6</a>; compare v. 7 — forma masculina para um casal, Amônio, <em>Vi. Aristot.</em> p. 10, 6 Westerm. <span class=\"greek\">ἀμφοτέροις ἐχαρίσατο</span>, Lc 7.42; <span class=\"greek\">κατέβησαν ἀ.</span>, At 8.38; <span class=\"greek\">ἀ. οἱ νεανίσκοι</span>, GPt 9:37; <span class=\"greek\">ἀ. τὰ πλοῖα</span>, Lc 5.7; <span class=\"greek\">τὸν ἐπ’ ἀμφοτέροις θεόν</span>, <strong>Deus, que está sobre ambos</strong>, B 19:7; D 4:10.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἀμφότεροι\" data-meanings=\"ambos juntos\">οἱ ἀ.</span>, <strong>ambos juntos</strong> — latim <em>utrimque</em>; em contraste com <span class=\"greek\">οἱ δύο</span>, “cada um dos dois”, considerados separadamente, latim <em>uterque</em>; veja B-D-F §275, 8 —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀποκαταλλάσσειν τοὺς ἀμφότερους τῷ θεῷ\" data-meanings=\"reconciliar ambos com Deus\">ἀποκαταλλάσσειν τοὺς ἀ. τῷ θεῷ</span>, <strong>reconciliar ambos com Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2.16</a>; <span class=\"greek\">οἱ ἀ. ἐν ἑνὶ πνεύματι</span>, v. 18; <span class=\"greek\">τὰ ἀ. ἓν ποιεῖν</span>, v. 14. <strong>Qualquer um dos dois</strong>, D 7:3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Todos</strong>, mesmo quando mais de dois estão envolvidos — Diodoro Sículo 1, 75, 1, <span class=\"greek\">πρὸς ἀμφότερα</span> = “para tudo, em todos os aspectos”; PThéad 26, 4 [296 d.C.]; PGen 67, 5; 69, 4 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.16</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Φαρισαῖοι ὁμολογοῦσιν τὰ ἀμφότερα\" data-meanings=\"os fariseus reconhecem todas essas coisas\">Φαρισαῖοι ὁμολογοῦσιν τὰ ἀ.</span>, <strong>os fariseus creem em todas essas coisas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.8</a>. J. Bury, <em>ClR</em> 11, 1897, 393ss.; 15, 1901, 440; <em>ByzZ</em> 7, 1898, 469; 11, 1902, 111; Mlt. 80; Rdm. 77s. — M-M.</p>\n</section></article><article id=\"entry-amometos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμώμητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦amṓmētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(De <span class=\"greek\">μωμάομαι</span>, “culpar, censurar”; Homero e outros; Diodoro Sículo 33, 7, 3; Plutarco, <em>Mor.</em> 489a; EpArist 93; Fílon, <em>Aet. M.</em> 41; ISyriaW 2007; Sb 332; 367; PGM 13, 89; 603.) <strong>Irrepreensível, sem mácula</strong>, a respeito de cristãos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3.14</a>, com <span class=\"greek\">ἄσπιλος</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.15</a> v.l. — M-M. TW.</p>\n</section></article><article id=\"entry-amomon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄμωμον</h1><div class=\"entry-meta\"><span class=\"greek\">ου, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ámōmon⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Hipócrates e outros; Teofrasto, <em>HP</em> 9, 7, 2; Dioscórides 1, 15; PGM 4, 1311; Josefo, <em>Ant.</em> 20, 25; DELG s.v. <span class=\"greek\">ἄμωμον</span>: empréstimo oriental.) <strong>Amomo</strong>, planta aromática indiana, mencionada com <span class=\"greek\">κιννάμωμον</span>, <span class=\"greek\">θυμιάματα</span>, <span class=\"greek\">μύρον</span> e outras especiarias em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.13</a>. — RAC I 395.</p>\n</section></article><article id=\"entry-amomos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄμωμος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ámōmos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Hesíodo e posteriores; Arriano: 156 Fgm. 121 Jac.; CIG 1974; inscrição de Herodes: APF 1, 1901, 220; LXX; Test12Patr; TestAbr A; GrBar 1:2; Fílon, <em>Congr. Erud. Grat.</em> 106; Josefo, <em>Bell.</em> 5, 229 e outros; Justino; Melito.)</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Pertencente ao que está <strong>sem defeito ou mácula, sem defeito, sem mácula</strong>, da ausência de defeitos em animais sacrificiais — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 6.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">19.2</a> e outros; TestAbr A; Fílon, <em>Sacr. Abel.</em> 51; <em>Somn.</em> 1, 62; Mel., <em>P.</em> —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμνάδας ἀσπίλους καὶ ἀμώμους\" data-meanings=\"cordeiras sem mancha e sem defeito\">ἀμνάδας ἀσπίλους καὶ ἀ.</span>, GJs 4:3. Daí, de Cristo como cordeiro sacrificial: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ἀμνοῦ ἀμώμου καὶ ἀσπίλου\" data-meanings=\"como de cordeiro sem defeito e sem mancha\">ὡς ἀμνοῦ ἀ. καὶ ἀσπίλου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1.19</a> — Mel., <em>P.</em> 12, 78. Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑαυτὸν προσήνεγκεν ἄμωμον τῷ θεῷ\" data-meanings=\"apresentou-se a si mesmo como oferta sem mácula a Deus\">ἑαυτὸν προσήνεγκεν ἄ. τῷ θεῷ</span>, <strong>apresentou-se a si mesmo como oferta sem mácula a Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.14</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Pertencente ao que está <strong>sem culpa e, portanto, moralmente irrepreensível; irrepreensível</strong> — Semônides 4; Ésquilo, <em>Pers.</em> 185; Heródoto 2, 177; Teócrito 18, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2SA.22.24\" target=\"_blank\" rel=\"noopener noreferrer\">2Sm 22.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 14.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">17.24</a> e outros.</p>\n<p class=\"entry-text\"><strong>a. De pessoas.</strong> Sb 625; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.31.8\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 31.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.40.19\" target=\"_blank\" rel=\"noopener noreferrer\">40.19</a>; Fílon, <em>Mut. Nom.</em> 60; Josefo, <em>Ant.</em> 3, 279 com <span class=\"greek\">καθαρός</span>; Justino, <em>D.</em> 17, 1, 3; 35, 8; Mel., <em>P.</em> 44, 312, de Cristo. Da comunidade cristã: com <span class=\"greek\">ἅγιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">5.27</a>; com <span class=\"greek\">ἅγιος, ἀνέγκλητος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.22</a>; com <span class=\"greek\">ἄσπιλος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3.14</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τέκνα θεοῦ ἄμωμα\" data-meanings=\"filhos de Deus irrepreensíveis\">τέκνα θεοῦ ἄ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.15</a> — compare <span class=\"greek\">ἀμώμητος</span> —; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμωμοί εἰσιν\" data-meanings=\"são irrepreensíveis\">ἄ. εἰσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.5</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 24</a>; 1 Cl 50:2; ITr 13:3.</p>\n<p class=\"entry-text\"><strong>b. De características.</strong> Compare Josefo, <em>Ant.</em> 3, 27s., <span class=\"greek\">δίαιτα</span> = “modo de vida”: <span class=\"greek\">βούλησις</span>, 1 Cl 35:5; <span class=\"greek\">ὄψις</span>, 36:2; <span class=\"greek\">πρόσωπον</span>, IPol 1:1; <span class=\"greek\">χεῖρες</span>, com <span class=\"greek\">ἱεραί</span>, 1 Cl 33:4; <span class=\"greek\">διάνοια</span>, ITr 1:1; <span class=\"greek\">καρδία</span>, com <span class=\"greek\">καθαρά</span>, Hv 4, 2, 5 — compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.118.80\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 118.80</a> —; <span class=\"greek\">πρόθεσις</span>, com <span class=\"greek\">ὅσιος</span>, 1 Cl 45:7; <span class=\"greek\">συνείδησις</span>, com <span class=\"greek\">σεμνός, ἁγνός</span>, 1:3; compare Pol 5:3; <span class=\"greek\">χαρά</span>, IEph ins.; IMg 7:1; <span class=\"greek\">πνεῦμα</span>, ISm ins. — <strong>não o Espírito Santo</strong>, pois a saudação tem paralelos em IEph ins. e no emprego de <span class=\"greek\">ἄμωμος</span> em IRo; compare ITrall 1, IPol 1 —; <span class=\"greek\">ἑνότης</span>, IEph 4:2; <span class=\"greek\">προστάγματα</span>, 1 Cl 37:1.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμωμον παθεῖν\" data-meanings=\"sofrer como pessoa irrepreensível\">ἄμωμον παθεῖν</span>, <strong>sofrer como pessoa irrepreensível</strong>, a respeito de Cristo, MPol 17:2. — DELG s.v. <span class=\"greek\">μῶμος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-amomos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀμώμως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦amṓmōs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de <span class=\"greek\">ἄμωμος</span>: <strong>irrepreensivelmente, sem culpa</strong>; empregado com <span class=\"greek\">χαίρειν</span> em IRo ins.</p>\n</section></article><article id=\"entry-amon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμών</h1><div class=\"entry-meta\"><span class=\"greek\">ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Amṓn⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">אָמֹון</bdi>; em Josefo, <em>Ant.</em> 10, 46–48, <span class=\"greek\">Ἀμμών, ῶνα</span>.) <strong>Amom</strong>, na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.10</a> v.l. — o texto tem <span class=\"greek\">Ἀμώς</span>, veja o sentido 2 desse verbete —, filho de Manassés e pai de Josias; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1CH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Cr 3.14</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2KI.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">4Rs 21.18–26</a>, com as variantes textuais.</p>\n</section></article><article id=\"entry-amos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀμώς</h1><div class=\"entry-meta\"><span class=\"greek\">ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Amṓs⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Sobre o nome hebraico correspondente, veja EbNestle, <em>ZNW</em> 4, 1903, 188.) <strong>Amós</strong>, na genealogia de Jesus. <span class=\"sense-number\">1.</span> Pai de Matatias, filho de Naum, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.25</a>. <span class=\"sense-number\">2.</span> Filho de Manassés, pai de Josias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.10</a> — v.l. <span class=\"greek\">Ἀμών</span>, veja esse verbete —; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.23ss.</a> D.</p>\n</section></article><article id=\"entry-an-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦án⟧</span><span class=\"separator\">·</span><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"sense-number\">I.</span> Depois de relativos, <span class=\"greek\">ἐάν</span> — veja esse verbete — é frequentemente usado em lugar de <span class=\"greek\">ἄν</span>, mas os manuscritos variam muito; veja B-D-F §§107, 377; Mlt. 42ss., 165ss.; Mayser 152s.; Crönert 130s.; Thackeray 67; Dssm., <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"NB 30ss. [BS 202ss.]\" data-tooltip-text=\"A. Deissmann, Neue Bibelstudien (1897), pp. 30ss.; na tradução inglesa Bible Studies (1901), pp. 202ss.\">NB 30ss. [BS 202ss.]</span>. Partícula própria do grego, desde Homero, que denota um <strong>aspecto de contingência</strong> e não pode ser traduzida por uma única palavra portuguesa. Indica que a ação do verbo depende de alguma circunstância ou condição; o efeito de <span class=\"greek\">ἄν</span> sobre o significado da oração depende do modo e do tempo/aspecto do verbo com que ocorre. O emprego no NT corresponde, em linhas gerais, ao grego mais antigo, embora sua variedade seja mais limitada, como normalmente acontece no grego posterior. Em certas construções — veja <strong>aβ</strong> — aparece um aspecto de certeza; na maioria dos demais casos exprimem-se graus diversos de possibilidade ou condicionalidade, cuja tradução depende da construção e das partículas associadas.</p>\n<p class=\"entry-text\"><strong>a. <span class=\"greek\">ἄν</span> com aoristo ou imperfeito do indicativo.</strong> <strong>α.</strong> Denota ação repetida no passado, mas apenas sob determinadas condições, especialmente depois de relativos — B-D-F §367; Rob., índice. Com aoristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.30.42\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 30.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 9.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.14.47\" target=\"_blank\" rel=\"noopener noreferrer\">1Rs 14.47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 10.11</a>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅσοι ἂν ἥψαντο αὐτοῦ, ἐσῴζοντο\" data-meanings=\"todos quantos o tocavam eram curados\">ὅσοι ἂν ἥψαντο αὐτοῦ, ἐσῴζοντο</span>, <strong>todos quantos o tocavam eram curados</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.56</a>. Com imperfeito: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 1.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 13.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 7.11</a>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅπου ἂν εἰσεπορεύετο εἰς κώμας\" data-meanings=\"onde quer que entrasse nas aldeias; como costumava fazer\">ὅπου ἂν εἰσεπορεύετο εἰς κώμας</span>, <strong>onde quer que entrasse nas aldeias</strong>, como costumava fazer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.56</a>; veja A. Debrunner, <em>D. hellenist. Nebensatziterativpräteritum mit ἄν</em>, <em>Glotta</em> 11 (1920), 1–28. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθότι ἄν τις χρείαν εἶχεν\" data-meanings=\"conforme alguém tivesse necessidade; conforme cada um tivesse necessidade\">καθότι ἄν τις χρείαν εἶχεν</span>, <strong>conforme alguém tivesse necessidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">4.35</a>. Semelhantemente, <span class=\"greek\">ὡς ἂν ἤγεσθε</span> — v.l. <span class=\"greek\">ἀνήγεσθε</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.2</a>. Compare também <span class=\"greek\">ὅταν</span> 1bγ e δ.</p>\n<p class=\"entry-text\"><strong>β.</strong> Na apódose de uma condição contrária ao fato — irreal — com <span class=\"greek\">εἰ</span>; B-D-F §360. <span class=\"greek\">ἄν</span> nem sempre é empregado; veja as variantes de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.36</a>, B-D-F §360, 1; Mlt. 199ss.; P. Melcher, <em>De sermone Epicteteo</em> (1905), 75. <strong>א. Com imperfeito:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">4Mc 17.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/BAR.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Br 3.13</a>; ParJer 5.20; GrBar 6.6; ApcMos 39. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὗτος εἰ ἦν προφήτης, ἐγίνωσκεν ἄν\" data-meanings=\"se este fosse profeta, saberia — agora —; mas não sabe\">οὗτος εἰ ἦν προφήτης, ἐγίνωσκεν ἄν</span>, <strong>se este fosse profeta, saberia — agora —</strong>, mas não sabe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.39</a>. <span class=\"greek\">εἰ ἔχετε πίστιν …, ἐλέγετε ἄν</span>, <strong>se tivésseis fé…, diríeis</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.6</a>. <span class=\"greek\">εἰ ἐπιστεύετε Μωϋσεῖ, ἐπιστεύετε ἂν ἐμοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.46</a>. <span class=\"greek\">εἰ ἐμὲ ᾔδειτε, καὶ τὸν πατέρα μου ἄν ᾔδειτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.19</a>; compare v. 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">9.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">15.19</a>. <span class=\"greek\">εἰ ἔτι ἀνθρώποις ἤρεσκον, Χριστοῦ δοῦλος οὐκ ἂν ἤμην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.10</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">3.21</a>. <span class=\"greek\">εἰ ἑαυτοὺς διεκρίνομεν, οὐκ ἂν ἐκρινόμεθα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.31</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἦν ἐπὶ γῆς, οὐδ’ ἂν ἦν ἱερεύς\" data-meanings=\"se estivesse na terra, nem sequer seria sacerdote\">εἰ ἦν ἐπὶ γῆς, οὐδ’ ἂν ἦν ἱερεύς</span>, <strong>se estivesse na terra, nem sequer seria sacerdote</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8.4</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">4.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">8.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">11.15</a>.</p>\n<p class=\"entry-text\"><strong>ב. Com aoristo</strong>, colocando a suposição no passado: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.30.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 30.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 11.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 11.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">4Mc 2.20</a>; TestJob 7.9 e outros; ParJer 5.5; GrBar 8.7; PGiss 47, 17. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἐγένοντο αἱ δυνάμεις, πάλαι ἂν … μετενόησαν\" data-meanings=\"se os milagres tivessem sido realizados, há muito teriam se arrependido\">εἰ ἐγένοντο αἱ δυνάμεις, πάλαι ἂν … μετενόησαν</span>, <strong>se os milagres tivessem sido realizados, há muito teriam se arrependido</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.21</a>. <span class=\"greek\">εἰ ἔγνωσαν, οὐκ ἂν ἐσταύρωσαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 2.8</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.29</a>, citando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Is 1.9</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἐγνώκειτε, οὐκ ἂν κατεδικάσατε\" data-meanings=\"se tivésseis reconhecido, não teríeis condenado\">εἰ ἐγνώκειτε, οὐκ ἂν κατεδικάσατε</span>, <strong>se tivésseis reconhecido, não teríeis condenado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.7</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ ἠγαπᾶτέ με, ἐχάρητε ἄν\" data-meanings=\"se me amásseis, ter-vos-íeis alegrado\">εἰ ἠγαπᾶτέ με, ἐχάρητε ἄν</span>, <strong>se me amásseis, ter-vos-íeis alegrado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.28</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">11.21</a>. O mais-que-perfeito pode substituir o aoristo do indicativo — PGiss 79 II, 6; BGU 1141, 27s.: <span class=\"greek\">εἰ ἦσαν, μεμενήκεισαν ἄν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2.19</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.21</a> v.l. Em <span class=\"greek\">κἀγὼ ἐλθὼν σὺν τόκῳ ἂν αὐτὸ ἔπραξα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.23</a>, <span class=\"greek\">ἐλθών</span> funciona como prótase temporal irreal — B-D-F §360, 2 —; compare <span class=\"greek\">καὶ ἐλθὼν ἐγὼ ἐκομισάμην ἂν τὸ ἐμόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.27</a>. Semelhantemente, em <span class=\"greek\">ἐπεὶ οὐκ ἂν ἐπαύσαντο προσφερόμεναι;</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.2</a>, <span class=\"greek\">ἐπεί</span> funciona como prótase: <strong>do contrário — isto é, se os sacrifícios realmente tivessem produzido expiação duradoura — não teriam deixado de ser oferecidos?</strong></p>\n<p class=\"entry-text\"><strong>b. <span class=\"greek\">ἄν</span> com subjuntivo depois de relativos.</strong> A oração relativa funciona virtualmente como a prótase de uma sentença condicional do tipo futuro mais vívido ou presente geral — B-D-F §380, 1. <strong>α.</strong> Com futuro ou <em>impf.</em> na apódose — a abreviação é conservada tal como aparece no BDAG —, para indicar que a condição e seus resultados são concebidos no futuro, em ação única ou repetida: IG XIV 865, séc. VI a.C.; TestAbr B 4, p. 109, 10 [Stone p. 66]. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὃς δ’ ἂν ποιήσῃ καὶ διδάξῃ, οὗτος μέγας κληθήσεται\" data-meanings=\"quem quer que faça e ensine — isto é, se alguém fizer e ensinar — será chamado grande\">ὃς δ’ ἂν ποιήσῃ καὶ διδάξῃ, οὗτος μέγας κληθήσεται</span>, <strong>quem quer que faça e ensine — isto é, se alguém fizer e ensinar — será chamado grande</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.19</a>. <span class=\"greek\">ὃς ἂν ἐσθίῃ …, ἔνοχος ἔσται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.27</a>. <span class=\"greek\">οὓς ἐὰν</span> — v.l. <span class=\"greek\">ἂν</span> — <span class=\"greek\">δοκιμάσητε, τούτους πέμψω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16.3</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16.2</a>.</p>\n<p class=\"entry-text\"><strong>β.</strong> Com presente na apódose, para indicar que a condição e seus resultados envolvem ação repetida, independentemente do elemento temporal: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἃ ἂν ἐκεῖνος ποιῇ, ταῦτα καὶ ὁ υἱὸς ὁμοίως ποιεῖ\" data-meanings=\"tudo quanto ele faz, o Filho também faz igualmente\">ἃ ἂν ἐκεῖνος ποιῇ, ταῦτα καὶ ὁ υἱὸς ὁμοίως ποιεῖ</span>, <strong>tudo quanto ele faz, o Filho também faz igualmente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.19</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅπου ἐὰν αὐτὸν καταλάβῃ, ῥήσσει αὐτόν\" data-meanings=\"onde quer que o apanhe, convulsiona-o\">ὅπου ἐὰν</span> — v.l. <span class=\"greek\">ἂν</span> — <span class=\"greek\">αὐτὸν καταλάβῃ, ῥήσσει αὐτόν</span>, <strong>onde quer que o apanhe, convulsiona-o</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.18</a>. <span class=\"greek\">ὑμῖν ἐστὶν ἡ ἐπαγγελία …, ὅσους ἂν προσκαλέσηται κύριος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.39</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὃς ἐὰν βουληθῇ φίλος εἶναι τοῦ κόσμου, ἐχθρὸς τοῦ θεοῦ καθίσταται\" data-meanings=\"quem quiser ser amigo do mundo torna-se inimigo de Deus\">ὃς ἐὰν</span> — v.l. <span class=\"greek\">ἂν</span> — <span class=\"greek\">βουληθῇ φίλος εἶναι τοῦ κόσμου, ἐχθρὸς τοῦ θεοῦ καθίσταται</span>, <strong>quem quiser ser amigo do mundo torna-se inimigo de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.4</a>; compare <span class=\"greek\">ὅπου ἄν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">3.4</a> v.l.</p>\n<p class=\"entry-text\">Quando <span class=\"greek\">ὅς</span> ou <span class=\"greek\">ὅστις</span> aparece com subjuntivo sem <span class=\"greek\">ἄν</span> — compare IG XII/1, 671; CPR I, 24, 33; 25, 19; AcThom 93 [Aa II/2, 206], 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Is 7.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.31.4\" target=\"_blank\" rel=\"noopener noreferrer\">31.4</a> —, provavelmente é correta a leitura que dá o futuro do indicativo: <span class=\"greek\">ὅστις τηρήσῃ</span> — v.l. <span class=\"greek\">-σει</span> —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.10</a>. Para <span class=\"greek\">ὅσοι</span> sem <span class=\"greek\">ἄν</span>: PPetr I, 13, 3; 5; CPR I, 237, 3; IPergamon 249, 26, <span class=\"greek\">ὅσοι … ἐγλίπωσι τὴν πόλιν</span>; Vett. Val. 125, 16; <span class=\"greek\">ὅσοι μετανοήσωσιν καὶ καθαρίσωσιν</span>, Hs 8, 11, 3 — veja W. e Joly, aparato, quanto à tradição textual. Veja Reinhold 108; B-D-F §380, 4.</p>\n<p class=\"entry-text\"><strong>c. Em orações temporais</strong>, <span class=\"greek\">ἄν</span> ocorre com o subjuntivo quando se descreve um evento que pode e há de ocorrer, mas cuja ocorrência ainda não pode ser pressuposta com certeza. <strong>α. <span class=\"greek\">ὅταν</span></strong> — = <span class=\"greek\">ὅτε ἄν</span>; veja <span class=\"greek\">ὅταν</span> — com presente do subjuntivo indica ação que se repete regularmente — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 12.18</a>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅταν ἄρτον ἐσθίωσιν\" data-meanings=\"sempre que comem pão\">ὅταν ἄρτον ἐσθίωσιν</span>, <strong>sempre que comem pão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.2</a>; <span class=\"greek\">ὅταν λαλῇ τὸ ψεῦδος</span>, <strong>sempre que diz a mentira</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8.44</a>; <span class=\"greek\">ὅταν λέγῃ τις</span>, <strong>sempre que alguém diz</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3.4</a>. Com aoristo do subjuntivo, exprime ação futura concebida como já completada — Prólogo de Sirácida, linha 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 8.21</a>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅταν ποιήσητε πάντα\" data-meanings=\"quando tiverdes feito tudo\">ὅταν ποιήσητε πάντα</span>, <strong>quando tiverdes feito tudo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.10</a>; <span class=\"greek\">ὅταν ἔλθῃ ὁ κύριος</span>, <strong>quando o senhor tiver vindo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.40</a>; <span class=\"greek\">ὅταν ἔλθῃ ἐν τῇ δόξῃ</span>, <strong>quando vier em sua glória</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.38</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">16.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.35</a>; <span class=\"greek\">ὅταν πάλιν εἰσαγάγῃ τὸν πρωτότοκον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.6</a>.</p>\n<p class=\"entry-text\"><strong>β. <span class=\"greek\">ἡνίκα ἄν</span></strong>, <strong>toda vez que</strong> — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 1.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.33.22\" target=\"_blank\" rel=\"noopener noreferrer\">33.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.34.24\" target=\"_blank\" rel=\"noopener noreferrer\">34.24</a> e outros; POxy 104, 26; PTebt 317, 18, <span class=\"greek\">ἡνίκα ἐὰν εἰς τὸν νόμον παραγένηται</span>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡνίκα ἂν ἀναγινώσκηται Μωϋσῆς\" data-meanings=\"toda vez que Moisés é lido em voz alta\">ἡνίκα ἂν</span> — também <span class=\"greek\">ἐάν</span> nos manuscritos — <span class=\"greek\">ἀναγινώσκηται Μωϋσῆς</span>, <strong>toda vez que Moisés é lido em voz alta</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.15</a>; compare v. 16. <strong>γ. <span class=\"greek\">ὁσάκις ἐάν</span></strong>, <strong>todas as vezes que</strong>: <span class=\"greek\">ὁσάκις ἐὰν</span> — também <span class=\"greek\">ἄν</span> nos manuscritos — <span class=\"greek\">πίνητε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.25</a>; <span class=\"greek\">… ἐσθίητε</span>, v. 26.</p>\n<p class=\"entry-text\"><strong>δ. <span class=\"greek\">ὡς ἄν</span></strong>, <strong>assim que</strong> — PHib 59, 2; 66, 4; PEleph 9, 3; PParis 46, 18; BGU 1209, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 11.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 15.9</a>: <span class=\"greek\">ὡς ἂν πορεύωμαι</span>, <strong>assim que eu viajar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.24</a>; <span class=\"greek\">ὡς ἂν ἔλθω</span>, <strong>assim que eu vier</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.34</a>; <span class=\"greek\">ὡς ἂν ἀφίδω τὰ περὶ ἐμέ</span>, <strong>assim que eu vir como vão as coisas a meu respeito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.23</a>. <span class=\"greek\">ὡς ἐάν</span>: PFay 111, 16; Hv 3, 8, 9; 3, 13, 2. <span class=\"greek\">ἀφ’ οὗ ἄν</span>, <strong>depois que</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.25</a>.</p>\n<p class=\"entry-text\">Com partículas temporais que indicam um termo — <span class=\"greek\">ἕως οὗ</span>, <span class=\"greek\">ἄχρις (οὗ)</span>, <span class=\"greek\">μέχρις (οὗ)</span> — os manuscritos mostram variação considerável; a adição de <span class=\"greek\">ἄν</span> provavelmente é correta apenas em casos raros — B-D-F §383, 2. Somente <span class=\"greek\">ἕως ἄν</span> tem atestação segura — PPetr II, 40a, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 24.14</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.49.10\" target=\"_blank\" rel=\"noopener noreferrer\">49.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 23.30</a> e outros —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μείνατε ἕως ἂν ἐξέλθητε\" data-meanings=\"permanecei até sairdes\">μείνατε ἕως ἂν ἐξέλθητε</span>, <strong>permanecei até sairdes</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.11</a>; <span class=\"greek\">ἕως ἂν ἴδωσιν τὴν βασιλείαν τοῦ θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.27</a>; também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">5.26</a>; <span class=\"greek\">ἕως ἂν λάβῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.7</a> v.l. <span class=\"greek\">ἄχρις οὗ</span> + <span class=\"greek\">ἄν</span> v.l., <span class=\"greek\">ἔλθῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.26</a>; <span class=\"greek\">ἄχρις οὗ</span> + <span class=\"greek\">ἄν</span> v.l., <span class=\"greek\">θῇ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">15.25</a>; <span class=\"greek\">ἄχρις οὗ ἂν ἥξω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2.25</a>, v.l. <span class=\"greek\">ἄχρι</span>; <span class=\"greek\">ἄχρις ἂν ἔλθῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.19</a> v.l.; compare BGU 830, 13. <span class=\"greek\">πρὶν ἄν</span>: <span class=\"greek\">πρὶν ἢ ἂν</span> — vv.ll. <span class=\"greek\">πρὶν ἄν</span>, <span class=\"greek\">πρὶν ἢ</span>, apenas <span class=\"greek\">πρίν</span> ou <span class=\"greek\">ἕως ἄν</span> — <span class=\"greek\">ἴδῃ τὸν Χριστόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.26</a>; B-D-F §383, 3.</p>\n<p class=\"entry-text\"><strong>d. Em orações finais.</strong> O ático <span class=\"greek\">ὅπως ἄν</span> — E. Hermann, <em>Griech. Forschungen</em> I (1912), 267s.; J. Knuenz, <em>De enuntiatis Graec. finalibus</em> (1913), 13ss.; 26ss. —, especialmente frequente em inscrições mais antigas — Meisterhans³-Schw. 254 —, tornou-se bastante raro; a LXX ainda o emprega com frequência: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 18.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.50.20\" target=\"_blank\" rel=\"noopener noreferrer\">50.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.33.13\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 33.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 7.23</a> e outros. <span class=\"greek\">ὅπως ἂν ἀποκαλυφθῶσιν διαλογισμοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.35</a>. <span class=\"greek\">ὅπως ἂν ἔλθωσιν καιροί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.20</a>; também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">15.17</a>, citando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/AMO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Am 9.12</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.4</a>, citando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.50.6\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 50.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.5</a> v.l.</p>\n<p class=\"entry-text\"><strong>e. O optativo com <span class=\"greek\">ἄν</span> em oração principal — optativo potencial —</strong> quase desapareceu. Exemplo raro: <span class=\"greek\">εὐξαίμην</span> — v.l. <span class=\"greek\">εὐξάμην</span> — <span class=\"greek\">ἄν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.29</a>, na fala de Paulo diante de Agripa, em uso literário; veja B-D-F §385, 1; Rob. 938; Temístio 6, p. 80 D. Sobre a raridade do optativo potencial em papiros, LXX e Pais Apostólicos, veja C. Harsing, <em>De Optat. in Chartis Aeg. Usu</em>, diss. Bonn (1910), 28; Reinhold 111. Compare, também na linguagem literária de Lucas, perguntas retóricas diretas — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 23.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 19.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.25.3\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 25.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">4Mc 7.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">14.10</a> v.l.; TestJob 13.5, <span class=\"greek\">τίς ἄν δώῃ</span>, e 35.5 —: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πῶς γὰρ ἂν δυναίμην;\" data-meanings=\"como, pois, eu poderia?\">πῶς γὰρ ἂν δυναίμην;</span>, <strong>como, pois, eu poderia?</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.31</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί ἂν θέλοι οὗτος λέγειν;\" data-meanings=\"que quererá este dizer?; que poderia este querer dizer?\">τί ἂν θέλοι οὗτος λέγειν;</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.18</a>. Dg preserva também o optativo como marca de estilo elegante: 2.3, 10; 3.3s.; 4.5; 7.2s.; 8.3; MPol 2.2 tem <span class=\"greek\">τίς οὐκ ἂν θαυμάσειεν;</span>.</p>\n<p class=\"entry-text\">É mais frequente em pergunta indireta, depois de imperfeito ou presente histórico — B-D-F §386, 1; Rob. 938s.: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ τί ἂν θέλοι καλεῖσθαι αὐτό\" data-meanings=\"como queria que a criança fosse chamada\">τὸ τί ἂν θέλοι καλεῖσθαι αὐτό</span>, <strong>como queria que a criança fosse chamada</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.62</a>; <span class=\"greek\">τίς ἂν εἴη περὶ οὗ λέγει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.24</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ τίς ἂν εἴη μείζων αὐτῶν\" data-meanings=\"qual deles seria o maior\">τὸ τίς ἂν εἴη μείζων αὐτῶν</span>, <strong>qual deles seria o maior</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.46</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.36\" target=\"_blank\" rel=\"noopener noreferrer\">18.36</a> v.l.; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τί ἂν ποιήσαιεν τῷ Ἰησοῦ\" data-meanings=\"o que fariam a Jesus\">τί ἂν ποιήσαιεν τῷ Ἰησοῦ</span>, <strong>o que fariam a Jesus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.11</a>; <span class=\"greek\">τί ἂν γένοιτο τοῦτο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.24</a>; <span class=\"greek\">τί ἂν εἴη τὸ ὅραμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.17</a>. Compare IMagnMai 215, séc. I d.C., e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EST.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Et 3.13c</a>.</p>\n<p class=\"entry-text\"><strong>f.</strong> O emprego de <span class=\"greek\">ἄν</span> com infinitivo e particípio, frequente no grego mais antigo, <strong>não ocorre de modo algum no NT</strong> — B-D-F §396. Em <span class=\"greek\">ἵνα μὴ δόξω ὡς ἂν</span> — ou <span class=\"greek\">ὡσὰν</span>, veja esse verbete — <span class=\"greek\">ἐκφοβεῖν ὑμᾶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10.9</a>, deve-se certamente explicar <span class=\"greek\">ὡς ἂν</span> como o latim <em>quasi</em>: <strong>não gostaria que parecesse que eu vos estou amedrontando</strong>; veja B-D-F §453, 3; Mlt. 167. Sobre <span class=\"greek\">εἰ μήτι ἂν</span> — subentenda-se <span class=\"greek\">γένηται</span> — <span class=\"greek\">ἐκ συμφώνου</span>, <strong>exceto, talvez, por acordo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.5</a>, veja B-D-F §376; Mlt. 169. — M-M.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">II.</span> <span class=\"greek\">ἄν</span> em lugar de <span class=\"greek\">ἐάν</span> é raro no grego helenístico — B-D-F §107; Mlt. 43 n. 2; compare Hipérides 4.5; 5.15; Teles, p. 31, 6; Plutarco, <em>Mor.</em> 547a; Epicteto, índice de Schenkl; papiros, Mayser 152; inscrições, especialmente do mar Egeu, Rdm.² 198, 3; veja também SIG, índice IV 204; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Ed 2.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">4Mc 16.11</a>; Josefo, <em>Ant.</em> 4.70; 219; Test12Patr; Mel., <em>Fgm.</em> 8b, 24 —, mas aparece em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">16.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">20.23</a>; e como variante em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">5.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">9.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">12.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">19.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.2</a>; IMg 10.1. — Mlt. 63, 1. M-M.</p>\n</section></article>"};
